-- The installer enables hypridle.service; do not start a second instance here.
-- Generated by hyprlang2lua. Review TODOs before reloading Hyprland.

-- Slow app launch fix -- set systemd vars

-- Run post-boot hooks after startup config has loaded

hl.on("hyprland.start", function()
    hl.exec_cmd("uwsm-app -- mako")
    hl.exec_cmd("! solace-toggle-enabled waybar-off && uwsm-app -- waybar")
    hl.exec_cmd("uwsm-app -- fcitx5 --disable notificationitem")
    hl.exec_cmd("uwsm-app -- swaybg -i ~/.config/solace/current/background -m fill")
    hl.exec_cmd("/usr/lib/polkit-gnome/polkit-gnome-authentication-agent-1")
    hl.exec_cmd("solace-welcome --first-run")
    hl.exec_cmd("solace-first-run")
    hl.exec_cmd("solace-powerprofiles-init")
    hl.exec_cmd("uwsm-app -- solace-hyprland-monitor-watch")
    hl.exec_cmd("systemctl --user import-environment $(env | cut -d'=' -f 1)")
    hl.exec_cmd("dbus-update-activation-environment --systemd --all")
    hl.exec_cmd("sleep 1 && solace-theme-refresh")
    hl.exec_cmd("sleep 2 && solace-hook post-boot")
end)
